def simulated_increment(schedule):
    # Sequential toy state machine, NOT execution of a C++ data race.
    if type(schedule) is not str or len(schedule)!=4 or schedule.count("A")!=2 or schedule.count("B")!=2:
        raise ValueError("expected two steps each for A and B")
    value=0
    step={"A":0,"B":0}
    local={}
    for worker in schedule:
        if step[worker]==0:
            local[worker]=value
        else:
            value=local[worker]+1
        step[worker]+=1
    return value

for schedule in ["AABB","ABAB","ABBA","BAAB","BABA","BBAA"]:
    print(schedule,simulated_increment(schedule))

#include <array>
#include <cstddef>
#include <iostream>
#include <thread>

int main() {
    const std::array<int,6> values{1,2,3,4,5,6};
    std::array<long long,2> partial{0,0};
    {
        std::jthread first([&values,&partial]() noexcept {
            long long sum=0;
            for(std::size_t i=0;i<3;++i)sum+=values[i];
            partial[0]=sum;
        });
        std::jthread second([&values,&partial]() noexcept {
            long long sum=0;
            for(std::size_t i=3;i<values.size();++i)sum+=values[i];
            partial[1]=sum;
        });
        // No main-thread partial reads here. Handles destroyed before referents.
    } // jthread destructors request stop and join their still-joinable threads.
    std::cout<<partial[0]<<' '<<partial[1]<<'\n';
    std::cout<<partial[0]+partial[1]<<'\n';
}
